sys_script_include.script:
// MSSCUSTODY-4148 - Script to get trade details for GCS.
var GCSTradeDetailsUtils = Class.create();
GCSTradeDetailsUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getTradeData: function(tradeID) {
        try {
            var reasonCodeDCCUK = gs.getProperty('x_hsb11_mss_c_proc.ReasonCodeForGCSDccUK');
            var reasonCodeGCCUK = gs.getProperty('x_hsb11_mss_c_proc.ReasonCodeForGCSGcUK');
            var reasonCodeDCCEU = gs.getProperty('x_hsb11_mss_c_proc.ReasonCodeForGCSDccEU');
            var reasonCodeGCEU = gs.getProperty('x_hsb11_mss_c_proc.ReasonCodeForGCSGcEU');
            var trdUniqVal = '';

            var trdIDClient = this.getParameter('sysparm_trdID');


            //client or server input.
            if (tradeID) {
                trdUniqVal = tradeID;
            } else {
                trdUniqVal = trdIDClient;
            }

            var trdData = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            trdData.get(trdUniqVal);
            if (trdUniqVal) {
                //     var tradeDetails = {

                //         'transactType': trdData.getValue('transaction_type'),
                //         'sourceSystem': trdData.getValue('source_system'),
                //         'fxLocation': trdData.getValue('fx_location'),
                //         'contractType': trdData.getValue('contract_type'),
                //         'owningBusiness': trdData.getValue('owning_business'),
                //         'rCodeDCC': reasonCodeDCCUK,
                //         'rCodeGC': reasonCodeGCCUK
                //     };
                var owningBus = trdData.getValue('owning_business').toString();

                // default to empty; set based on market
                var rCodeDCC = '';
                var rCodeGC = '';

                if (owningBus.indexOf('UK') > -1) {
                    rCodeDCC = reasonCodeDCCUK;
                    rCodeGC = reasonCodeGCCUK;
                } else if (owningBus.indexOf('EU') > -1) {
                    rCodeDCC = reasonCodeDCCEU;
                    rCodeGC = reasonCodeGCEU;
                }

                tradeDetails = {
                    'transactType': trdData.getValue('transaction_type'),
                    'sourceSystem': trdData.getValue('source_system'),
                    'fxLocation': trdData.getValue('fx_location'),
                    'contractType': trdData.getValue('contract_type'),
                    'owningBusiness': owningBus,
                    'rCodeDCC': rCodeDCC,
                    'rCodeGC': rCodeGC
                };
            }

            var tradeJson = JSON.stringify(tradeDetails);
            return tradeJson;
        } catch (e) {
            gs.info("Script Include - GCSTradeDetailsUtils - Unexpected Error While Processing" + e.message);
        }

    },


    getTradeDataforGCSUK: function(tradeID) {
        // MSSCUSTODY-4763 - Added function to get details of Trans Ref entered by user.
        try {
            var reasonCodeDCCUK = gs.getProperty('x_hsb11_mss_c_proc.ReasonCodeForGCSDccUK');
            var reasonCodeGCCUK = gs.getProperty('x_hsb11_mss_c_proc.ReasonCodeForGCSGcUK');
            var trdUniqVal = '';

            var trdIDClient = this.getParameter('sysparm_trdID');


            //client or server input
            if (tradeID) {
                trdUniqVal = tradeID;
            } else {
                trdUniqVal = trdIDClient;
            }

            var trdData = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            trdData.addEncodedQuery('trade_idLIKE' + trdUniqVal);
            trdData.query();
            if (trdData.next()) {
                var tradeDetails = {

                    'transactType': trdData.getValue('transaction_type'),
                    'sourceSystem': trdData.getValue('source_system'),
                    'fxLocation': trdData.getValue('fx_location'),
                    'contractType': trdData.getValue('contract_type'),
                    'owningBusiness': trdData.getValue('owning_business'),
                    'rCodeDCC': reasonCodeDCCUK,
                    'rCodeGC': reasonCodeGCCUK
                };
            }

            var tradeJson = JSON.stringify(tradeDetails);
            return tradeJson;
        } catch (e) {
            gs.info("Script Include - GCSTradeDetailsUtils - Unexpected Error While Processing" + e.message);
        }

    },

    //MSSCUSTODY-6087
    getDefaultIndicator: function(tradeId) {

        try {
            var tradeGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            tradeGR.addEncodedQuery('trade_idLIKE' + tradeId);
            tradeGR.query();
            if (tradeGR.next()) {
                var indicator = tradeGR.getValue('gdi_indicator').toString();
                if (indicator === 'Auto Generation') return 'Auto Generation';
                if (indicator === 'Not Generate') return 'Not Generate';
            }
            return 'Not Generate'; // fallback
        } catch (e) {
            gs.info("Script Include - GCSTradeDetailsUtils - Unexpected Error While Processing" + e.message);
        }
    },




    type: 'GCSTradeDetailsUtils'
});
